            aCross ^= (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 9781U)) & S_BLOCK1], 5U) ^ RotL64(aKeyRowReadA[(((2047U - aIndex) + 8734U)) & W_KEY1], 29U));
            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCross, 5U) ^ RotL64(aIngress, 51U)) + (RotL64(aPrevious, 38U) ^ RotL64(aCarry, 21U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
