            aOrbiterG = (aWandererG + RotL64(aIngress, 43U)) + 0x934BBB0CDF495A38ULL;
            aOrbiterK = (aWandererC + RotL64(aScatter, 14U)) + 0x8FAD68391D9CBECBULL;
