            aOrbiterK = (aOrbiterK + aOrbiterA) + 0xE8F4CCA7ABBA968DULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0x59F6CBEBF14DEEDBULL) ^ aOUSaltG[((aIndex + 355U)) & S_SALT1];
