            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x56AAF43330E1248DULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterI) ^ 0xE63CEF78665B8A45ULL) ^ aOUSaltD[(((511U - aIndex) + 219U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xF0D63176B4539E77ULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x624997BF3E85EA1DULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x95F749E8A294F898ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x4E88A1B812B60CA1ULL), 53U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0x5A4954D021B59721ULL) + aOUSaltC[(((511U - aIndex) + 402U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x7C7AE29AF2FDC6C2ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF247314210759DE1ULL), 23U);
