            aWandererB = aWandererB ^ ((RotL64(aScatter, 57U) + RotL64(aOrbiterD, 5U)) + aOrbiterF);
            aWandererJ = aWandererJ + ((RotL64(aCross, 11U) + RotL64(aOrbiterK, 53U)) + aOrbiterI);
