            aOrbiterC = RotL64((aOrbiterC * 0xE64E97D4A188575BULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xCAB549BD09623E1FULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x9B0173882DA07232ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x268661C5AA46BD01ULL), 3U);
