            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x7D3AB548541B45C8ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0x9D0142F69C57D6EDULL) ^ aOUSaltC[((aIndex + 189U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x0874526F143561EBULL), 19U);
