            //
            aIngress = (RotL64(aWindLaneD[((aIndex + 7819U)) & S_BLOCK1], 18U) ^ RotL64(aWindLaneB[((aIndex + 1135U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(aCrystalLaneA[((aIndex + 4820U)) & S_BLOCK1], 29U) ^ RotL64(aAetherLaneC[((aIndex + 856U)) & S_BLOCK1], 47U));
