            aOrbiterG = ((aWandererK + RotL64(aIngress, 37U)) + RotL64(aCarry, 51U)) + 0x1367942EBD2B373FULL;
            aOrbiterC = ((aWandererI + RotL64(aCross, 23U)) + 0x45A5CBDF2F92D505ULL) + aOASaltC[(((511U - aIndex) + 480U)) & S_SALT1];
            aOrbiterB = (aWandererC + RotL64(aPrevious, 27U)) + 0xAE72E77F33CAED23ULL;
            aOrbiterD = ((aWandererG + RotL64(aIngress, 53U)) + 0xA56FB9535018EE57ULL) + aOASaltG[((aIndex + 208U)) & S_SALT1];
            aOrbiterH = ((aWandererE + RotL64(aPrevious, 3U)) + RotL64(aCarry, 39U)) + 0xA3C7681EB7B35AF9ULL;
            aOrbiterF = (aWandererJ + RotL64(aCross, 30U)) + 0x2EE69D95F9896FC4ULL;
